// (src/libraries/System.Runtime.InteropServices.JavaScript/ref/System.Runtime.InteropServices.JavaScript.cs).
// NetWasm adaptations: the binding surface .NET's JSImport and JSExport generators call, so a library built for the
// browser by .NET's SDK (Microsoft.Testing.Platform's browser console) compiles; every member throws
// PlatformNotSupportedException, as the assembly does on .NET's platforms without a browser. NetWasm's own JSImport
// and JSExport, which the compiler binds, do not use it. JSHost.GlobalThis and JSHost.ImportAsync work: NetWasm
// binds a program's JavaScript modules before it starts, so an import completes with the module already bound.

namespace System.Runtime.InteropServices.JavaScript
{
    internal static class JSBindingSupport
    {
        internal const string Message = "JavaScript bindings generated by .NET's JSImport and JSExport generators are not supported on NetWasm; use NetWasm's JSImport and JSExport.";
    }
    public static class JSHost
    {
        public static JSObject GlobalThis => JSHostModule.GlobalThis();

        public static JSObject DotnetInstance { get => throw new PlatformNotSupportedException(JSBindingSupport.Message); }

        // NetWasm binds a program's JavaScript modules, the build's NetWasmJavaScriptModule items and those its host
        // supplies, before the program starts. Importing one completes with it, as .NET's import of a module name it
        // already imported does, whatever the URL; a module the host does not have fails the task.
        public static System.Threading.Tasks.Task<JSObject> ImportAsync(string moduleName, string moduleUrl, System.Threading.CancellationToken cancellationToken = default)
        {
            if (cancellationToken.IsCancellationRequested)
            {
                return System.Threading.Tasks.Task.FromCanceled<JSObject>(cancellationToken);
            }
            if (string.IsNullOrEmpty(moduleName) || string.IsNullOrEmpty(moduleUrl))
            {
                return System.Threading.Tasks.Task.FromException<JSObject>(
                    new JSException("A JavaScript module import needs a module name and a URL."));
            }
            var module = JSHostModule.Bound(moduleName);
            return module is null
                ? System.Threading.Tasks.Task.FromException<JSObject>(new JSException(
                    "JavaScript module '" + moduleName + "' is not bound; declare it with a NetWasmJavaScriptModule item or supply it to the host."))
                : System.Threading.Tasks.Task.FromResult(module);
        }
    }

    // The global object and the modules the host bound, served by the runtime's own import module.
    internal static class JSHostModule
    {
        private const string Module = "netwasm.host.v1";

        [JSImport("host_global_this", Module)]
        internal static extern JSObject GlobalThis();

        [JSImport("host_module", Module)]
        internal static extern JSObject? Bound(string moduleName);
    }

